function validarNovela(datos) {
  if (typeof datos.titulo !== 'string' || !datos.titulo.trim()) {
    throw new Error('El título es obligatorio');
  }
  if (!Number.isInteger(datos.volumenes) || datos.volumenes < 0) {
    throw new Error('volumenes debe ser un entero no negativo');
  }
  return { titulo: datos.titulo.trim(), volumenes: datos.volumenes };
}

